    <style>
        :root {
            --bg: #0f172a;
            --panel: #1e293b;
            --accent: #38bdf8;
            --accent-soft: rgba(56, 189, 248, 0.1);
            --text: #e2e8f0;
            --text-muted: #94a3b8;
            --success: #34d399;
            --warning: #fbbf24;
            --border: #334155;
            --font-mono: 'JetBrains Mono', 'Fira Code', 'Courier New', monospace;
            --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
        }

        * { box-sizing: border-box; margin: 0; padding: 0; }

        body {
            background-color: var(--bg);
            color: var(--text);
            font-family: var(--font-sans);
            display: flex;
            flex-direction: column;
            align-items: center;
            min-height: 100vh;
            padding: 20px;
            overflow-x: hidden;
            transition: filter 0.2s;
        }

        /* --- Header --- */
        header {
            width: 100%;
            max-width: 900px;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 12px;
            margin-bottom: 24px;
        }

        h1 {
            font-size: 1.8rem;
            font-weight: 700;
            background: linear-gradient(90deg, #38bdf8, #818cf8);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            letter-spacing: -0.5px;
        }

        .subtitle {
            color: var(--text-muted);
            font-size: 0.9rem;
            text-align: center;
            max-width: 600px;
        }

        /* --- The Diagram --- */
        #viewport {
            width: 100%;
            max-width: 800px;
            height: 400px;
            background: var(--panel);
            border: 1px solid var(--border);
            border-radius: 16px;
            position: relative;
            overflow: hidden;
            box-shadow: 0 4px 24px rgba(0,0,0,0.5);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            z-index: 10;
        }

        #canvas-layer {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none;
            z-index: 1;
        }

        /* --- Control Bar --- */
        .controls {
            display: flex;
            gap: 12px;
            margin-bottom: 20px;
            flex-wrap: wrap;
            justify-content: center;
        }

        button {
            background: var(--accent);
            color: #0f172a;
            border: none;
            padding: 10px 20px;
            border-radius: 8px;
            font-weight: 600;
            cursor: pointer;
            font-size: 0.9rem;
            transition: transform 0.1s, filter 0.2s, background 0.2s;
            font-family: var(--font-sans);
        }

        button:hover {
            filter: brightness(1.1);
            transform: translateY(-1px);
        }

        button:active {
            transform: scale(0.96);
        }

        button.secondary {
            background: transparent;
            border: 1px solid var(--accent);
            color: var(--accent);
        }
        button.secondary:hover {
            background: var(--accent-soft);
        }

        #step-label {
            margin-bottom: 10px;
            font-size: 1.1rem;
            font-weight: 600;
            color: var(--accent);
            min-height: 1.6em;
            text-align: center;
        }

        /* --- Tooltip / Legend --- */
        .legend {
            display: flex;
            gap: 16px;
            flex-wrap: wrap;
            justify-content: center;
            margin-bottom: 24px;
            font-size: 0.8rem;
            color: var(--text-muted);
        }
        .legend span { display: flex; align-items: center; gap: 6px; }
        .dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }

        /* --- Animation Elements --- */
        .node {
            position: absolute;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            transition: transform 0.3s;
            z-index: 2;
        }
        .node svg { width: 64px; height: 64px; }
        .node-label {
            margin-top: 8px;
            font-size: 0.75rem;
            font-weight: 700;
            color: var(--text);
            text-align: center;
            background: rgba(15, 23, 42, 0.8);
            padding: 2px 8px;
            border-radius: 10px;
            border: 1px solid var(--border);
        }

        .packet {
            position: absolute;
            z-index: 3;
            pointer-events: none;
            transition: top 0.5s linear, left 0.5s linear;
            width: 24px;
            height: 24px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            font-weight: bold;
        }

        .active-stage {
            border-color: var(--accent) !important;
            box-shadow: 0 0 20px var(--accent-soft);
            transform: scale(1.1);
            z-index: 20;
        }
        .active-stage .node-label {
            color: var(--accent);
            background: rgba(56, 189, 248, 0.2);
            border-color: var(--accent);
        }

        /* --- Tech Details --- */
        .tech-specs {
            max-width: 700px;
            background: var(--panel);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 20px;
            margin-top: 20px;
            font-size: 0.9rem;
            line-height: 1.6;
            color: var(--text-muted);
            position: relative;
            z-index: 20;
        }
        .tech-specs h3 {
            color: var(--text);
            margin-top: 0;
            margin-bottom: 8px;
            font-size: 1rem;
        }
        .tech-specs ul { padding-left: 16px; }
        .tech-specs li { margin-bottom: 4px; }

        /* --- SVG Specifics --- */
        .char-face { fill: none; stroke: currentColor; stroke-width: 2; }
        .char-fill { fill: currentColor; }
        .path-d { fill: var(--accent); stroke: var(--accent); stroke-width: 2; }

        /* --- Responsive --- */
        @media (max-width: 600px) {
            #viewport { height: 340px; }
            .node svg { width: 48px; height: 48px; }
            h1 { font-size: 1.4rem; }
        }

        /* --- Reduced Motion --- */
        @media (prefers-reduced-motion: reduce) {
            .packet, .node { transition: none !important; animation: none !important; }
            button:hover { transform: none; }
        }
    </style>
</head>
